/**
 * QTI 3.0.1's response and template processing, as the database's declared functions: the machine
 * plate's grader was, ported from the prototype the golden oracle proves equal to plate. Generated
 * by @qti-pie/ledger's tools/gen/grading.ts from the SQL of its machine/ (`pnpm --filter
 * @qti-pie/ledger generate`); edit the SQL and generate again, and `generate:check` refuses any
 * other edit.
 */
import {
  closed,
  closedId,
  fn,
  natural,
  pg,
  row,
  rows,
  sha256,
  str,
  uuid,
} from "@bjornpagen/grizzle";
import { admissionCodes } from "@qti-pie/plate/admission-codes";
import { QtiIdentifier } from "@qti-pie/pantry/qti/limits.ts";
import { CreditKind } from "#ledger/credit.ts";
import { anyText, LearnerId, someText } from "#ledger/keys.ts";
import { QtiInteger } from "#ledger/scalars.ts";

/**
 * A number's exact value, a float's rational one among them: a signature's numeric, which no typmod
 * bounds.
 */
const exactNumber = pg.numeric;

/**
 * QTI 3.0.1's base types and cardinalities.
 */
const BaseType = str.regex(
  "^(boolean|directedPair|duration|file|float|identifier|integer|pair|point|string|uri)$",
);

const Cardinality = str.regex("^(multiple|ordered|record|single)$");

/**
 * How a run goes on: it runs, it exits, or a template constraint restarts it.
 */
const Flow = str.regex("^(exit|restart|run)$");

/**
 * The processing language's element kinds: QTI 3.0.1's rules and expressions.
 */
const ProcessingKind = str.regex(
  "^(qti-and|qti-any-n|qti-base-value|qti-container-size|qti-contains|qti-correct|qti-custom-operator|qti-default|qti-delete|qti-divide|qti-duration-gte|qti-duration-lt|qti-equal|qti-equal-rounded|qti-exit-response|qti-exit-template|qti-exit-test|qti-field-value|qti-gcd|qti-gt|qti-gte|qti-index|qti-inside|qti-integer-divide|qti-integer-modulus|qti-integer-to-float|qti-is-null|qti-lcm|qti-lookup-outcome-value|qti-lt|qti-lte|qti-map-response|qti-map-response-point|qti-match|qti-math-constant|qti-math-operator|qti-max|qti-member|qti-min|qti-multiple|qti-not|qti-null|qti-number-correct|qti-number-incorrect|qti-number-presented|qti-number-responded|qti-number-selected|qti-or|qti-ordered|qti-outcome-condition|qti-outcome-else|qti-outcome-else-if|qti-outcome-if|qti-outcome-maximum|qti-outcome-minimum|qti-outcome-processing|qti-outcome-processing-fragment|qti-pattern-match|qti-power|qti-product|qti-random|qti-random-float|qti-random-integer|qti-repeat|qti-response-condition|qti-response-else|qti-response-else-if|qti-response-if|qti-response-processing|qti-response-processing-fragment|qti-round|qti-round-to|qti-set-correct-response|qti-set-default-value|qti-set-outcome-value|qti-set-template-value|qti-stats-operator|qti-string-match|qti-substring|qti-subtract|qti-sum|qti-template-condition|qti-template-constraint|qti-template-else|qti-template-else-if|qti-template-if|qti-template-processing|qti-test-variables|qti-truncate|qti-variable)$",
);

const AreaKind = str.regex("^(circle|ellipse|everywhere|nowhere|poly|rect)$");

const LookupKind = str.regex("^(interpolation|match)$");

const ToleranceMode = str.regex("^(absolute|exact|relative)$");

const RoundingMode = str.regex("^(decimalPlaces|significantFigures)$");

const MathOperator = str.regex(
  "^(abs|acos|acot|acsc|asec|asin|atan|atan2|ceil|cos|cosh|cot|coth|csc|csch|exp|floor|ln|log|sec|sech|signum|sin|sinh|tan|tanh|toDegrees|toRadians)$",
);

const StatOperator = str.regex("^(mean|popSD|popVariance|sampleSD|sampleVariance)$");

const MathConstant = str.regex("^(e|pi)$");

/**
 * Which of an attempt's values a boundary row holds: its value now, its correct response or its
 * default in force.
 */
const Holds = str.regex("^(correct|default|value)$");

/**
 * Which bound of a tolerance band a comparison reads.
 */
const BoundSide = str.regex("^(lower|upper)$");

/**
 * The registered custom operators' classes, the Registry level's roster (src/registry/operators.ts'
 * customOperators).
 */
const CustomOperatorClass = str.regex(
  "^(markup-text|math-canonical|normalize-space|numeral-normal|phrase-distance|quantity|read-number|rubric-score|tex-normal|tokenize|translate|unit-near|when-present)$",
);

/**
 * The roles a class reads the registry's tables in (tools/gen/grading/machine.ts).
 */
const TableRole = str.regex(
  "^(competitors|contrast-words|glue-words|ie-plurals|letter-units|never-plural|operation-words|plurals|stop-words|typo-targets|unit-spellings|unit-words|verbs)$",
);

/**
 * Math-canonical's token kinds (tools/gen/grading/machine.ts).
 */
const MathTokenKind = str.regex("^(fn|joiner|name|num|op|rel|sqrt)$");

/**
 * Math-canonical's node kinds (tools/gen/grading/machine.ts).
 */
const MathNodeKind = str.regex(
  "^(abs|div|fact|fn|frac|mixed|name|neg|num|pct|pow|prod|rel|root|sum|tuple)$",
);

/**
 * Math-canonical's parse modes (tools/gen/grading/machine.ts).
 */
const MathParseMode = str.regex("^(factor|group|sum)$");

/**
 * The kind of declaration an item variable a test reads through its item ref has, a built-in under
 * its own kind's (QTI 3.0.1's four variable declarations: ContextDeclaration, ResponseDeclaration,
 * OutcomeDeclaration and TemplateDeclaration, Tables 5.34, 5.115, 4.5 and 5.151).
 */
const VariableKind = str.regex("^(context|outcome|response|template)$");

/**
 * Which declared bound of an outcome a test's outcome-minimum or outcome-maximum reads (Table
 * 4.5.7, 4.5.8).
 */
const BoundKind = str.regex("^(maximum|minimum)$");

/**
 * Which category filter of a test-level expression a category belongs to (Tables 7.39.2 and
 * 7.39.3).
 */
const CategoryFilter = str.regex("^(exclude|include)$");

/**
 * Which one-word parameter of an element a walk's name row is (document.sql's walk_from): a
 * test-variables' base-type, a math constant's, math operator's or stats operator's name, a
 * field-value's field-identifier, and a test expression's section-identifier and
 * weight-identifier.
 */
const WalkNameField = str.regex("^(base|constant|field|math|section|stat|weight)$");

/**
 * Which number-or-variable parameter a walk's integer, float or ref row is: an any-n's max and min,
 * an equal's tolerance's first and second, a random float's max and min, an index's n or a repeat's
 * number-repeats, a random integer's max, min and step, and a rounding's figures.
 */
const WalkNumberField = str.regex(
  "^(any_n\\.max|any_n\\.min|equal\\.t0|equal\\.t1|frange\\.hi|frange\\.lo|int\\.value|range\\.hi|range\\.lo|range\\.step|round\\.figures)$",
);

/**
 * Which parameter a walk's ref row names a variable for: a number-or-variable parameter, or a
 * pattern-match's pattern where it is {VAR}, a declared variable's identifier in braces.
 */
const WalkRefField = str.regex(
  "^(any_n\\.max|any_n\\.min|equal\\.t0|equal\\.t1|frange\\.hi|frange\\.lo|int\\.value|pattern|range\\.hi|range\\.lo|range\\.step|round\\.figures)$",
);

/**
 * A review's mark on a part of a response (AttemptMark, marks.sql): right, wrong, or a correct
 * value missed.
 */
const AnswerMark = str.regex("^(missed|right|wrong)$");

/**
 * The elements of an item's declarations the machine reads (QTI 3.0.1's four variable declarations,
 * their default and correct values, their mappings and lookup tables): what a statement passes of a
 * document's declarations, by kind.
 */
export const declarationParts = [
  "qti-response-declaration",
  "qti-outcome-declaration",
  "qti-template-declaration",
  "qti-context-declaration",
  "qti-default-value",
  "qti-correct-response",
  "qti-value",
  "qti-mapping",
  "qti-map-entry",
  "qti-area-mapping",
  "qti-area-map-entry",
  "qti-match-table",
  "qti-match-table-entry",
  "qti-interpolation-table",
  "qti-interpolation-table-entry",
] as const;

const DeclarationPart = str.regex(
  "^(qti-response-declaration|qti-outcome-declaration|qti-template-declaration|qti-context-declaration|qti-default-value|qti-correct-response|qti-value|qti-mapping|qti-map-entry|qti-area-mapping|qti-area-map-entry|qti-match-table|qti-match-table-entry|qti-interpolation-table|qti-interpolation-table-entry)$",
);

/**
 * The attributes of a processing program's and a declaration's elements the machine reads, by name.
 */
export const gradedAttributes = [
  "base-type",
  "cardinality",
  "case-sensitive",
  "coords",
  "default-value",
  "field-identifier",
  "identifier",
  "include-boundary",
  "lower-bound",
  "map-key",
  "mapped-value",
  "shape",
  "source-value",
  "target-value",
  "upper-bound",
] as const;

const GradedAttribute = str.regex(
  "^(base-type|cardinality|case-sensitive|coords|default-value|field-identifier|identifier|include-boundary|lower-bound|map-key|mapped-value|shape|source-value|target-value|upper-bound)$",
);

