/**
 * The closed roster of admission's reason codes, plate's `admissionCodes` (generated with this
 * module from admission.sql's admission_one `codes`): a reason's `code` is its id, which
 * admission_one writes as its handle's place in that list, from 0, and grizzle numbers the same way
 * and never renumbers.
 */
export const AdmissionCode = closed.ordered("AdmissionCode", admissionCodes);

/**
 * The attributes of the item body's elements admission reads, by name: what a statement passes of
 * the body.
 */
export const admittedAttributes = [
  "response-identifier",
  "identifier",
  "max-choices",
  "min-choices",
  "max-associations",
  "min-associations",
  "match-max",
  "match-min",
  "match-group",
  "required",
  "template-identifier",
  "outcome-identifier",
  "show-hide",
  "hotspot-label",
  "aria-label",
  "width",
  "height",
  "center-point",
  "lower-bound",
  "upper-bound",
  "step",
  "max-plays",
  "min-plays",
  "max-strings",
  "min-strings",
  "pattern-mask",
  "format",
] as const;

const AdmittedAttribute = str.regex(
  "^(response-identifier|identifier|max-choices|min-choices|max-associations|min-associations|match-max|match-min|match-group|required|template-identifier|outcome-identifier|show-hide|hotspot-label|aria-label|width|height|center-point|lower-bound|upper-bound|step|max-plays|min-plays|max-strings|min-strings|pattern-mask|format)$",
);

/**
 * A reason's attributes by form: words (an identifier, an axis, a group's members), counts and
 * numbers.
 */
const AdmissionWordName = str.regex("^(subject|other|group|axis)$");

const AdmissionCountName = str.regex("^(n|at|extent)$");

const AdmissionNumberName = str.regex("^(width|height|bound|step)$");

