    field_points: DocFieldPoint,
    field_texts: DocFieldText,
    files: DocFile,
    floats: DocFloat,
    integers: DocInteger,
    member_bounds: TestMemberBound,
    members: TestMember,
    pairs: DocPair,
    points: DocPoint,
    programs: ProgramNode,
    ref_categories: TestRefCategory,
    ref_mappings: TestRefMapping,
    ref_sections: TestRefSection,
    ref_weights: TestRefWeight,
    runs: DocumentRun,
